+fn remote_terminal_session(
+    session: &Arc<crate::terminal::PtySession>,
+    cache: &WorkspaceSnapshotCache,
+) -> RemoteTerminalSession {
+    let running = matches!(
+        session.state(),
+        PtySessionState::Running | PtySessionState::Starting
+    );
+    let (workspace_id, worktree_label) =
+        cache.derive_session_metadata(session.worktree_path().as_deref());
+    RemoteTerminalSession {
+        session_id: session.id().to_string(),
+        title: None,
+        workspace_id,
+        worktree_label,
+        running,
+    }
