+fn relative_label(root: &Path, canonical: &Path) -> Option<String> {
+    if let Ok(rel) = canonical.strip_prefix(root) {
+        if !rel.as_os_str().is_empty() {
+            return Some(
+                rel.to_string_lossy()
+                    .replace(std::path::MAIN_SEPARATOR, "/"),
